<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('manager');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO lowongan(id_divisi,judul_lowongan,job_description,job_specification,jumlah_kebutuhan,deadline) VALUES(?,?,?,?,?,?)');$s->execute([user()['id_divisi'],trim($_POST['judul']),trim($_POST['desc']),trim($_POST['spec']),max(1,(int)$_POST['jumlah']),$_POST['deadline']?:null]);flash('Pengajuan berhasil dikirim ke HR.');header('Location: dashboard.php');exit;}page_header('Ajukan Kebutuhan Lowongan');?><div class="card"><form method="post"><label>Job Title<input name="judul" required></label><label>Jumlah Karyawan<input type="number" name="jumlah" min="1" required></label><label>Job Description<textarea name="desc" required></textarea></label><label>Job Specification<textarea name="spec" required></textarea></label><label>Deadline (opsional)<input type="date" name="deadline"></label><button class="btn">Kirim Pengajuan</button></form></div><?php page_footer();
